"""Futuris Predictive Risk & Forecasting Bridge.

Correlates machine-learning probabilistic attack vector forecasts from Futuris
with active Sentinel asset inventories to provide dynamic threat posture escalation.
"""

from __future__ import annotations

from typing import Any

from pydantic import BaseModel, Field

from sentinel.audit.audit_logger import audit_logger
from sentinel.core.models import RiskTier


class FuturisThreatForecast(BaseModel):
    """Predictive attack vector forecast generated by Futuris."""

    forecast_id: str
    target_asset_category: str  # e.g., "api_endpoints", "cloud_storage", "dns_infrastructure"
    predicted_vector: str  # e.g., "credential_stuffing", "ransomware_campaign", "zero_day_exploit"
    probability_score: float = Field(ge=0.0, le=1.0)
    horizon_hours: int = 72
    confidence: float = Field(default=0.8, ge=0.0, le=1.0)
    recommended_posture_tier: RiskTier = RiskTier.MEDIUM
    supporting_signals: list[str] = Field(default_factory=list)
    metadata: dict[str, Any] = Field(default_factory=dict)


class PostureAdjustment(BaseModel):
    """Actionable posture adjustments recommended to Sentinel orchestration."""

    forecast_id: str
    target_category: str
    current_tier: RiskTier
    recommended_tier: RiskTier
    escalation_applied: bool
    scan_frequency_multiplier: float = 1.0
    rationale: str = ""


class FuturisForecastingBridge:
    """Consumes forecasts from Futuris and computes dynamic risk tier adjustments."""

    def __init__(self) -> None:
        self._active_forecasts: dict[str, FuturisThreatForecast] = {}
        self._category_postures: dict[str, RiskTier] = {}

    def ingest_forecast(self, forecast: FuturisThreatForecast) -> PostureAdjustment:
        """Process incoming Futuris forecast and dynamically escalate defensive posture."""
        self._active_forecasts[forecast.forecast_id] = forecast
        category = forecast.target_asset_category.lower().strip()

        current_tier = self._category_postures.get(category, RiskTier.LOW)
        target_tier = forecast.recommended_posture_tier

        # Determine escalation
        tier_weights = {
            RiskTier.MINIMAL: 1,
            RiskTier.LOW: 2,
            RiskTier.MEDIUM: 3,
            RiskTier.HIGH: 4,
            RiskTier.CRITICAL: 5,
        }

        escalation_applied = False
        scan_multiplier = 1.0

        if tier_weights.get(target_tier, 2) > tier_weights.get(current_tier, 2) and forecast.probability_score >= 0.6:
            self._category_postures[category] = target_tier
            escalation_applied = True
            scan_multiplier = 2.0 if target_tier in (RiskTier.HIGH, RiskTier.CRITICAL) else 1.5
            rationale = (
                f"Escalated posture for '{category}' from {current_tier.value} to {target_tier.value} "
                f"due to Futuris forecast (probability={forecast.probability_score:.2f}, vector='{forecast.predicted_vector}')."
            )
        else:
            rationale = (
                f"Maintained existing posture {current_tier.value} for '{category}'; "
                f"forecast probability ({forecast.probability_score:.2f}) below threshold."
            )

        audit_logger.log_event(
            event_type="FUTURIS_FORECAST_INGESTED",
            actor="futuris",
            target=category,
            action_type="predictive_posture_adjustment",
            scope_policy="predictive_defense_policy",
            decision="POSTURE_ESCALATED" if escalation_applied else "POSTURE_MAINTAINED",
            details={
                "forecast_id": forecast.forecast_id,
                "vector": forecast.predicted_vector,
                "probability": forecast.probability_score,
                "current_tier": current_tier.value,
                "new_tier": self._category_postures.get(category, current_tier).value,
                "escalation_applied": escalation_applied,
            },
        )

        return PostureAdjustment(
            forecast_id=forecast.forecast_id,
            target_category=category,
            current_tier=current_tier,
            recommended_tier=self._category_postures.get(category, current_tier),
            escalation_applied=escalation_applied,
            scan_frequency_multiplier=scan_multiplier,
            rationale=rationale,
        )

    def get_effective_posture(self, category: str) -> RiskTier:
        """Retrieve current effective posture for an asset category."""
        return self._category_postures.get(category.lower().strip(), RiskTier.LOW)
